const live = typeof window !== "undefined";
const tabs = [...this.querySelectorAll(".tabs-tab")];
const panels = [...this.querySelectorAll(".tabs-panel")];
const show = (index) => {
  tabs.forEach((tab, i) => { tab.classList.toggle("is-active", i === index); tab.setAttribute("aria-selected", String(i === index)); tab.tabIndex = i === index ? 0 : -1; });
  panels.forEach((panel, i) => { panel.hidden = i !== index; });
  this.dataset.active = String(index);
};
this.style.setProperty("--tabs-accent", props.accent);
show(Math.min(Math.max(Number(props.active) || 0, 0), tabs.length - 1));
if (live) {
  tabs.forEach((tab, i) => tab.addEventListener("click", () => show(i)));
  this.addEventListener("keydown", (event) => {
    if (!["ArrowRight", "ArrowLeft"].includes(event.key)) return;
    const next = (Number(this.dataset.active) + (event.key === "ArrowRight" ? 1 : tabs.length - 1)) % tabs.length;
    show(next); tabs[next].focus();
  });
}

