.tabs-tab { cursor: pointer; border: 0; background: none; padding: 8px 2px; color: rgba(0, 0, 0, 0.55); border-bottom: 2px solid transparent; transition: color 0.2s ease, border-color 0.2s ease; }
.tabs-tab:hover { color: rgba(0, 0, 0, 0.85); }
.tabs-tab:focus-visible { outline: 2px solid var(--tabs-accent); outline-offset: 2px; }
.tabs-tab.is-active { color: var(--tabs-accent); border-bottom-color: var(--tabs-accent); }
@media (prefers-reduced-motion: reduce) { .tabs-tab { transition: none; } }
